      "clearConfirmDescription_one": "\u0633\u064a\u0624\u062f\u064a \u0630\u0644\u0643 \u0623\u064a\u0636\u064b\u0627 \u0625\u0644\u0649 \u062d\u0630\u0641 \u0645\u0642\u0627\u0644 \u0645\u062b\u0628\u062a \u0648\u0627\u062d\u062f\u060c \u0648\u0644\u0627 \u064a\u0645\u0643\u0646 \u0627\u0644\u062a\u0631\u0627\u062c\u0639 \u0639\u0646\u0647. ({{count}})",
      "clearConfirmDescription_two": "\u0633\u064a\u0624\u062f\u064a \u0630\u0644\u0643 \u0623\u064a\u0636\u064b\u0627 \u0625\u0644\u0649 \u062d\u0630\u0641 \u0645\u0642\u0627\u0644\u064a\u0646 \u0645\u062b\u0628\u062a\u064a\u0646\u060c \u0648\u0644\u0627 \u064a\u0645\u0643\u0646 \u0627\u0644\u062a\u0631\u0627\u062c\u0639 \u0639\u0646\u0647. ({{count}})",
      "clearConfirmDescription_few": "\u0633\u064a\u0624\u062f\u064a \u0630\u0644\u0643 \u0623\u064a\u0636\u064b\u0627 \u0625\u0644\u0649 \u062d\u0630\u0641 {{count}} \u0645\u0642\u0627\u0644\u0627\u062a \u0645\u062b\u0628\u062a\u0629\u060c \u0648\u0644\u0627 \u064a\u0645\u0643\u0646 \u0627\u0644\u062a\u0631\u0627\u062c\u0639 \u0639\u0646\u0647.",
