        "restoreDescription": "\u0623\u062f\u062e\u0644 \u0643\u0644\u0645\u0629 \u0645\u0631\u0648\u0631 \u062a\u0634\u0641\u064a\u0631 \u0627\u0644\u0645\u0632\u0627\u0645\u0646\u0629 \u0627\u0644\u062d\u0627\u0644\u064a\u0629 \u0645\u0646 \u0623\u0648\u0644 \u062c\u0647\u0627\u0632 \u062a\u0645\u062a \u0645\u0632\u0627\u0645\u0646\u062a\u0647. \u0647\u0630\u0647 \u0644\u064a\u0633\u062a \u0643\u0644\u0645\u0629 \u0645\u0631\u0648\u0631 \u062d\u0633\u0627\u0628 Supertry.",
        "encryptedTitle": "\u0645\u0634\u0641\u0651\u0631 \u062a\u0645\u0627\u0645\u064b\u0627 \u0628\u064a\u0646 \u0627\u0644\u0637\u0631\u0641\u064a\u0646",
        "encryptedDescription": "\u062a\u064f\u0634\u0641\u0651\u0631 \u0628\u064a\u0627\u0646\u0627\u062a\u0643 \u0639\u0644\u0649 \u062c\u0647\u0627\u0632\u0643. \u0644\u0627 \u064a\u0645\u0643\u0646\u0646\u0627 \u0631\u0624\u064a\u0629 \u0639\u0644\u0627\u0645\u0627\u062a \u062a\u0628\u0648\u064a\u0628\u0643 \u0645\u0637\u0644\u0642\u064b\u0627.",
        "realtimeTitle": "\u0645\u0632\u0627\u0645\u0646\u0629 \u0641\u064a \u0627\u0644\u0648\u0642\u062a \u0627\u0644\u0641\u0639\u0644\u064a",
        "realtimeDescription": "\u062a\u062a\u0632\u0627\u0645\u0646 \u0627\u0644\u062a\u063a\u064a\u064a\u0631\u0627\u062a \u0641\u0648\u0631\u064b\u0627 \u0628\u064a\u0646 \u062c\u0645\u064a\u0639 \u0623\u062c\u0647\u0632\u062a\u0643.",
