        "existingPasswordPlaceholder": "\u0623\u062f\u062e\u0644 \u0643\u0644\u0645\u0629 \u0645\u0631\u0648\u0631 \u0627\u0644\u0645\u0632\u0627\u0645\u0646\u0629",
