        "freshWarning": "\u0633\u064a\u0637\u0644\u0628 \u0647\u0630\u0627 \u0645\u0646 Supertry \u0645\u0633\u062d \u0628\u064a\u0627\u0646\u0627\u062a \u0627\u0644\u0645\u0632\u0627\u0645\u0646\u0629 \u0627\u0644\u0633\u062d\u0627\u0628\u064a\u0629 \u0627\u0644\u0645\u0634\u0641\u0651\u0631\u0629 \u0627\u0644\u0642\u062f\u064a\u0645\u0629 \u0642\u0628\u0644 \u0631\u0628\u0637 \u0647\u0630\u0627 \u0627\u0644\u0645\u062a\u0635\u0641\u062d \u0628\u0643\u0644\u0645\u0629 \u0645\u0631\u0648\u0631 \u0645\u0632\u0627\u0645\u0646\u0629 \u062c\u062f\u064a\u062f\u0629.",
        "restoreWarning": "\u0627\u0633\u062a\u062e\u062f\u0645 \u0643\u0644\u0645\u0629 \u0645\u0631\u0648\u0631 \u0627\u0644\u0645\u0632\u0627\u0645\u0646\u0629 \u0646\u0641\u0633\u0647\u0627 \u0645\u0646 \u0627\u0644\u0625\u0639\u062f\u0627\u062f \u0627\u0644\u0623\u0635\u0644\u064a. \u0625\u0630\u0627 \u0644\u0645 \u062a\u0643\u0646 \u0642\u062f \u0623\u0646\u0634\u0623\u062a \u0643\u0644\u0645\u0629 \u0645\u0631\u0648\u0631 \u0644\u0644\u0645\u0632\u0627\u0645\u0646\u0629 \u0623\u0648 \u0644\u0627 \u064a\u0645\u0643\u0646\u0643 \u062a\u0630\u0643\u0631\u0647\u0627\u060c \u0641\u0644\u0646 \u064a\u0645\u0643\u0646\u0646\u0627 \u0627\u0633\u062a\u0639\u0627\u062f\u062a\u0647\u0627.",
